import uuid

app = Flask(__name__)

STATE = {
    'sites': {},
    'families': {},
    'children': {},
    'classrooms': {},
    'invoices': {},
    'payments': {},
    'waiting_list': [],
    'audit_log': [],
}


def new_id(prefix):
    return f"{prefix}_{uuid.uuid4().hex[:8]}"


def today_iso():
    return date.today().isoformat()


def child_status(child):
    imm = child.get('immunization_status', 'missing')
    classroom = STATE['classrooms'].get(child.get('classroom_id'))
    if classroom:
        cap = classroom['capacity']
        enrolled = classroom['enrolled_count']
        capacity_status = 'full' if enrolled >= cap else 'available'
    else:
        capacity_status = 'unassigned'
    return {
        'immunization_status': imm,
        'classroom_status': capacity_status,
        'is_compliant': imm in {'current', 'due_soon', 'exempt'},
    }


def recalc_classroom_counts():
    for c in STATE['classrooms'].values():
        c['enrolled_count'] = 0
    for child in STATE['children'].values():
        cid = child.get('classroom_id')
        if cid in STATE['classrooms']:
            STATE['classrooms'][cid]['enrolled_count'] += 1


@app.get('/health')
def health():
    return jsonify({'ok': True})


@app.post('/sites')
def create_site():
    payload = request.get_json(force=True)
    site_id = new_id('site')
    STATE['sites'][site_id] = {'id': site_id, 'name': payload['name']}
    return jsonify(STATE['sites'][site_id]), 201


@app.post('/families')
def create_family():
    payload = request.get_json(force=True)
    family_id = new_id('fam')
    STATE['families'][family_id] = {
        'id': family_id,
        'name': payload['name'],
        'contact': payload.get('contact', {}),
        'site_id': payload.get('site_id'),
        'billing_unified': True,
    }
    return jsonify(STATE['families'][family_id]), 201


@app.post('/children')
def create_child():
    payload = request.get_json(force=True)
    family_id = payload['family_id']
    if family_id not in STATE['families']:
        abort(404)
    child_id = new_id('child')
    STATE['children'][child_id] = {
        'id': child_id,
        'family_id': family_id,
        'name': payload['name'],
        'dob': payload.get('dob'),
        'classroom_id': None,
        'attendance': [],
        'immunization_status': payload.get('immunization_status', 'missing'),
        'allergies': payload.get('allergies', []),
        'pickup_authority': payload.get('pickup_authority', []),
        'compliance_reviewed': False,
    }
    return jsonify(STATE['children'][child_id]), 201


@app.post('/classrooms')
def create_classroom():
    payload = request.get_json(force=True)
    cid = new_id('cls')
    STATE['classrooms'][cid] = {
        'id': cid,
        'name': payload['name'],
        'site_id': payload.get('site_id'),
        'capacity': int(payload['capacity']),
        'enrolled_count': 0,
    }
    return jsonify(STATE['classrooms'][cid]), 201


@app.post('/children/<child_id>/assign')
def assign_child(child_id):
    payload = request.get_json(force=True)
    child = STATE['children'].get(child_id)
    classroom = STATE['classrooms'].get(payload['classroom_id'])
    if not child or not classroom:
        abort(404)
    if classroom['enrolled_count'] >= classroom['capacity'] and not payload.get('override'):
        return jsonify({'error': 'classroom full'}), 409
    child['classroom_id'] = classroom['id']
    recalc_classroom_counts()
    return jsonify(child)


@app.post('/children/<child_id>/checkin')
def checkin(child_id):
    child = STATE['children'].get(child_id)
    if not child:
        abort(404)
    child['attendance'].append({'date': today_iso(), 'check_in': True, 'check_out': False})
    return jsonify({'status': 'checked_in'})


@app.post('/children/<child_id>/checkout')
def checkout(child_id):
    child = STATE['children'].get(child_id)
    if not child:
        abort(404)
    child['attendance'].append({'date': today_iso(), 'check_in': False, 'check_out': True})
    return jsonify({'status': 'checked_out'})


@app.get('/families/<family_id>')
def get_family(family_id):
    fam = STATE['families'].get(family_id)
    if not fam:
        abort(404)
    fam = dict(fam)
    fam['children'] = [c for c in STATE['children'].values() if c['family_id'] == family_id]
    return jsonify(fam)


@app.get('/children/<child_id>')
def get_child(child_id):
    child = STATE['children'].get(child_id)
    if not child:
        abort(404)
    data = dict(child)
    data['status'] = child_status(child)
    return jsonify(data)


@app.post('/invoices')
def create_invoice():
    payload = request.get_json(force=True)
    inv_id = new_id('inv')
    STATE['invoices'][inv_id] = {
        'id': inv_id,
        'family_id': payload['family_id'],
        'amount': float(payload['amount']),
        'balance': float(payload['amount']),
        'status': 'open',
        'adjustments': [],
        'payments': [],
    }
    return jsonify(STATE['invoices'][inv_id]), 201


@app.post('/payments')
def make_payment():
    payload = request.get_json(force=True)
    invoice = STATE['invoices'].get(payload['invoice_id'])
    if not invoice:
        abort(404)
    amount = float(payload['amount'])
    payment = {
        'id': new_id('pay'),
        'invoice_id': invoice['id'],
        'amount': amount,
        'payer': payload.get('payer', 'account_holder'),
        'status': 'recorded',
    }
    if amount > invoice['balance']:
        payment['status'] = 'rejected'
        STATE['payments'][payment['id']] = payment
        return jsonify({'error': 'payment exceeds balance', 'payment': payment}), 400
    invoice['balance'] -= amount
    invoice['payments'].append(payment['id'])
    if invoice['balance'] == 0:
        invoice['status'] = 'paid'
    STATE['payments'][payment['id']] = payment
    return jsonify({'payment': payment, 'invoice': invoice})


@app.get('/dashboard')
def dashboard():
    recalc_classroom_counts()
    return jsonify({
        'sites': len(STATE['sites']),
        'families': len(STATE['families']),
        'children': len(STATE['children']),
        'classrooms': list(STATE['classrooms'].values()),
        'waiting_list': STATE['waiting_list'],
    })


@app.post('/waiting-list')
def add_waiting_list():
    payload = request.get_json(force=True)
    entry = {'id': new_id('wait'), 'family_id': payload['family_id'], 'child_name': payload['child_name'], 'requested_site': payload.get('site_id')}
    STATE['waiting_list'].append(entry)
    return jsonify(entry), 201


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8000, debug=False)
EOF

